-- Desactivar verificaciones de claves foráneas
PRAGMA foreign_keys=OFF;

-- Tabla: locations
DROP TABLE IF EXISTS locations;
CREATE TABLE locations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            departamento_codigo VARCHAR(10) NOT NULL,
            municipio_codigo VARCHAR(10),
            zona_codigo VARCHAR(10),
            puesto_codigo VARCHAR(10),
            mesa_codigo VARCHAR(10),
            departamento_nombre VARCHAR(100) NOT NULL,
            municipio_nombre VARCHAR(100),
            puesto_nombre VARCHAR(200),
            mesa_nombre VARCHAR(200),
            nombre_completo VARCHAR(500) NOT NULL,
            tipo VARCHAR(50) NOT NULL,
            total_votantes_registrados INTEGER DEFAULT 0,
            mujeres INTEGER DEFAULT 0,
            hombres INTEGER DEFAULT 0,
            comuna VARCHAR(100),
            direccion VARCHAR(500),
            latitud FLOAT,
            longitud FLOAT,
            activo BOOLEAN DEFAULT 1 NOT NULL,
            parent_id INTEGER,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
            FOREIGN KEY (parent_id) REFERENCES locations (id),
            CHECK (tipo IN ('departamento', 'municipio', 'zona', 'puesto', 'mesa'))
        );

-- Datos de locations (396 registros)

-- Tabla: users
DROP TABLE IF EXISTS users;
CREATE TABLE users (
	id INTEGER NOT NULL, 
	nombre VARCHAR(100) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	rol VARCHAR(50) NOT NULL, 
	ubicacion_id INTEGER, 
	activo BOOLEAN NOT NULL, 
	ultimo_acceso DATETIME, 
	intentos_fallidos INTEGER NOT NULL, 
	bloqueado_hasta DATETIME, 
	presencia_verificada BOOLEAN NOT NULL, 
	presencia_verificada_at DATETIME, 
	ultima_latitud FLOAT, 
	ultima_longitud FLOAT, 
	ultima_geolocalizacion_at DATETIME, 
	precision_geolocalizacion FLOAT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, es_usuario_basico BOOLEAN DEFAULT FALSE NOT NULL, cedula VARCHAR(20), 
	PRIMARY KEY (id), 
	CONSTRAINT check_rol_valido CHECK (rol IN ('super_admin', 'admin_departamental', 'admin_municipal', 'coordinador_departamental', 'coordinador_municipal', 'coordinador_puesto', 'testigo_electoral', 'auditor_electoral', 'monitoreo'))
);

